mapper.sql:
WHERE r.delete_yn = 'N'

  AND r.status = #{search.status}


  AND r.target_type = #{search.targetType}


  AND r.reason_code = #{search.reasonCode}


  AND (
        r.reason_text LIKE CONCAT('%', #{search.keyword}, '%')
     OR u.login_id    LIKE CONCAT('%', #{search.keyword}, '%')
  )

